function bevelProcess(data,w,h,opts){
  opts=opts||{};
  var strength=opts.strength!=null?opts.strength:30;
  if(strength<0)strength=0; else if(strength>120)strength=120;
  var lum=new Float32Array(w*h);
  for(var i=0,y=0;y<h;y++) for(var x=0;x<w;x++,i++){ var p=(y*w+x)*4; lum[y*w+x]=0.299*data[p]+0.587*data[p+1]+0.114*data[p+2]; }
  function L(x,y){ if(x<0)x=0; else if(x>w-1)x=w-1; if(y<0)y=0; else if(y>h-1)y=h-1; return lum[y*w+x]; }
  var out=new Uint8ClampedArray(data.length);
  var k=strength/(255*6);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var p=(y*w+x)*4;
    var gx=(L(x-1,y-1)+L(x-1,y)+L(x-1,y+1))-(L(x+1,y-1)+L(x+1,y)+L(x+1,y+1));
    var gy=(L(x-1,y-1)+L(x,y-1)+L(x+1,y-1))-(L(x-1,y+1)+L(x,y+1)+L(x+1,y+1));
    var relief=gx+gy;
    var shade=1+relief*k;
    if(shade<0.3)shade=0.3; else if(shade>1.8)shade=1.8;
    out[p]=data[p]*shade; out[p+1]=data[p+1]*shade; out[p+2]=data[p+2]*shade; out[p+3]=data[p+3];
  }
  return out;
}

var EXPORTS={bevelProcess:bevelProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BevelForgePure = EXPORTS; }
